    #[test]
    fn a_problem_document_is_shown_by_status_and_detail() {
        let body =
            br#"{"type":"urn:x","title":"Not Found","status":404,"detail":"Project 1 not found"}"#;
        assert_eq!(
            describe_error(reqwest::StatusCode::NOT_FOUND, body),
            "404 Not Found: Project 1 not found"
        );
        assert_eq!(
            describe_error(reqwest::StatusCode::UNAUTHORIZED, b""),
            "401 Unauthorized"
        );
    }

    #[test]
    fn values_print_as_tables() {
        let rows = json!([{ "id": "a", "name": "one" }, { "id": "bb", "name": null }]);
        assert_eq!(table(&rows), "ID  NAME\na   one\nbb  -\n");
        assert_eq!(table(&json!({ "id": "a", "n": 1 })), "id  a\nn   1\n");
        assert_eq!(table(&json!([])), "(none)\n");
    }

    #[test]
    fn path_values_are_percent_encoded() {
        assert_eq!(encode("a b/c"), "a%20b%2Fc");
        assert_eq!(encode("plugin-1.0_x~"), "plugin-1.0_x~");
    }
